import { Browser, BrowserContext, BrowserContextOptions, expect, Locator, Page, TestInfo } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { addManualItem, stamp } from '../pricebook/pricebook-helpers';
import { setJobStatus } from '../job-closed-date/closed-helpers';

export const PREPROD = (process.env.QA_PREPROD_URL || 'https://techory-git-preprod-eli-s-projects-26be8857.vercel.app').replace(/\/$/, '');
export const pp = (p: string) => `${PREPROD}${p}`;

export const ROLE = 'preprod-ttp';
export const CLIENT = 'TTP Customer';
export const ITEM_PRICE = '5';
export const REMAINING = '$5.00';

/** Порядок способов на вебе (скрин 67b4b4-v2-take-a-payment-desktop.png; Tap to Pay — только в приложении). */
export const WEB_METHODS = ['Payment Link', 'Cash', 'Credit Card', 'Check', 'Bank Transfer', 'Other'] as const;

export { stamp };

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
export const amountRe = (amount: string) => new RegExp(`^\\s*${escapeRe(amount)}\\s*$`);

// ---------- Окно с сессией роли (для beforeAll — фикстура asUser там недоступна) ----------

const CONTEXT_KEYS = ['locale', 'viewport', 'userAgent', 'deviceScaleFactor', 'isMobile', 'hasTouch', 'timezoneId'] as const;

export async function openRoleContext(browser: Browser, testInfo: TestInfo): Promise<{ context: BrowserContext; page: Page }> {
  const storageState = path.resolve(__dirname, '../../../auth', `${ROLE}.json`);
  if (!fs.existsSync(storageState)) throw new Error(`Нет сессии «${ROLE}» (.qa/auth/${ROLE}.json). Запусти npm run qa-login:manual -- ${ROLE}`);
  const projectUse = testInfo.project.use as Record<string, unknown>;
  const opts: BrowserContextOptions = {};
  for (const k of CONTEXT_KEYS) if (projectUse[k] !== undefined) (opts as Record<string, unknown>)[k] = projectUse[k];
  const context = await browser.newContext({ ...opts, storageState });
  return { context, page: await context.newPage() };
}

// ---------- Без SMS / email ----------

/** Обрывает запросы отправки SMS/email; возвращает массив случившихся запросов (должен остаться пустым). */
export async function blockMessaging(page: Page): Promise<string[]> {
  const hits: string[] = [];
  await page.context().route(/send[-_]?(sms|email)|sendSms|sendEmail/i, async (route) => {
    hits.push(`${route.request().method()} ${route.request().url()}`);
    await route.abort();
  });
  return hits;
}

// ---------- Работа QA-AUTO с остатком $5.00 ----------

/** New Job → TTP Customer → Repair → описание «QA-AUTO pay …» → Create Job → Items: позиция $5 (или opts.price). Возвращает URL работы. */
export async function createJobWithBalance(page: Page, label: string, opts: { price?: string; ticket?: string } = {}): Promise<string> {
  const description = `QA-AUTO pay ${label} ${opts.ticket ?? '#67b4b4'} ${stamp()}`;
  await page.goto(pp('/JobForm?action=new'));
  const client = page.getByLabel('Client Name *');
  await client.pressSequentially('TTP Cust', { delay: 20 });
  await page.getByRole('button').filter({ hasText: CLIENT }).first().click();
  await expect(client).toHaveValue(CLIENT);
  const address = page.getByRole('textbox', { name: /^Address/ });
  if ((await address.count()) && (await address.first().inputValue()) === '') {
    await address.first().fill('QA-AUTO 1 Test Street');
    await page.keyboard.press('Escape');
  }
  await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
  await page.getByRole('option', { name: 'Repair', exact: true }).click();
  await page.getByLabel('Job Description').fill(description);
  await page.getByRole('button', { name: 'Create Job', exact: true }).click();
  await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
  const url = new URL(page.url());
  url.searchParams.delete('tab');
  const jobUrl = url.toString();

  url.searchParams.set('tab', 'items');
  await page.goto(url.toString());
  await expect(page.getByRole('button', { name: 'Add Item' }).first()).toBeVisible();
  await addManualItem(page, { name: `QA-AUTO pay-line ${stamp()}`, price: opts.price ?? ITEM_PRICE });
  return jobUrl;
}

/** Открыть работу → вкладка Payments (кнопка вкладки с подписью «Remaining to pay: $…»). */
export async function openPaymentsTab(page: Page, jobUrl: string) {
  await page.goto(jobUrl);
  await page.getByRole('main').getByText(/^Remaining to pay: \$/).first().click();
  await expect(page.getByRole('heading', { name: 'Job Payments' })).toBeVisible();
}

/** Карточка «Remaining to pay / $N / Take a payment» вверху вкладки. */
export function remainingCard(page: Page): Locator {
  return page.getByRole('main').locator('button, a, [role="button"], div')
    .filter({ has: page.getByText('Remaining to pay', { exact: true }) })
    .filter({ has: page.getByText('Take a payment', { exact: true }) })
    .last();
}

/** Нажать карточку → окно «Take a payment». */
export async function openTakeAPayment(page: Page): Promise<Locator> {
  await page.getByRole('main').getByText('Take a payment', { exact: true }).first().click();
  const dialog = page.getByRole('dialog').filter({ hasText: 'How is the customer paying?' });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole('heading', { name: 'Take a payment' }).or(dialog.getByText('Take a payment', { exact: true })).first()).toBeVisible();
  return dialog;
}

/** Названия способов в окне по порядку (кнопки-строки, первая строка текста). */
export async function methodNames(dialog: Locator): Promise<string[]> {
  const names = (await dialog.getByRole('button').allInnerTexts()).map((t) => t.split('\n')[0].trim()).filter(Boolean);
  return names.filter((n) => /^(Tap to Pay|Payment Link|Cash|Credit Card|Check|Bank Transfer|Other)$/.test(n));
}

export const methodButton = (dialog: Locator, name: string) =>
  dialog.getByRole('button').filter({ hasText: new RegExp(`^\\s*${escapeRe(name)}\\s*$`) }).first();

// ---------- Очистка (не роняет тест) ----------

/** Все открытые ссылки работы → Cancel link (+ подтверждение, если есть). */
export async function cancelOpenLinks(page: Page, jobUrl: string | null) {
  if (!jobUrl || page.isClosed()) return;
  try {
    await openPaymentsTab(page, jobUrl);
    const cancel = page.getByRole('main').getByRole('button', { name: /Cancel link/i });
    const n = await cancel.count();
    for (let i = 0; i < n; i++) {
      await cancel.first().click();
      const confirm = page.getByRole('alertdialog').or(page.getByRole('dialog')).getByRole('button', { name: /^(Cancel link|Yes|Confirm)/i });
      if (await confirm.count()) await confirm.first().click();
      await expect(cancel).toHaveCount(n - i - 1, { timeout: 10_000 });
    }
  } catch (e) {
    console.warn(`очистка ссылок оплаты (${jobUrl}) не удалась — отменить вручную: ${String(e).slice(0, 200)}`);
  }
}

/** Работа QA-AUTO → Cancelled. */
export async function cancelJob(page: Page, jobUrl: string | null) {
  if (!jobUrl || page.isClosed()) return;
  try {
    await page.goto(jobUrl);
    await setJobStatus(page, 'Cancelled');
  } catch (e) {
    console.warn(`очистка работы (${jobUrl}) не удалась — поставить Cancelled вручную: ${String(e).slice(0, 200)}`);
  }
}

