export const COMPANY = 'TTP Test Locks';
export const IS_PROD = /(^|\.)app\.techory\.ai$/.test(new URL(PREPROD).host);
export const escRe = escapeRe;

/** Номер работы «#JOB-0004» со страницы работы. */
export async function jobNumber(page: Page): Promise<string> {
  const el = page.getByRole('main').getByText(/^#JOB-\d+$/).first();
  await expect(el).toBeVisible();
  return (await el.innerText()).trim();
}

/** Remaining to pay → Payment Link → Create link → ссылка из поля (окно закрывается Done). Text / Email не нажимаются. */
export async function createPaymentLink(page: Page): Promise<string> {
  const choose = await openTakeAPayment(page);
  await methodButton(choose, 'Payment Link').click();
  const dialog = page.getByRole('dialog').filter({ hasText: /Payment link/i }).last();
  await expect(dialog).toBeVisible();
  await dialog.getByRole('button', { name: /^Create link$/i }).click();
  await expect(dialog.getByText('Link ready. Send it to the customer:')).toBeVisible({ timeout: 30_000 });
  const link = await dialog.getByRole('textbox').first().inputValue();
  await dialog.getByRole('button', { name: /^Done$/ }).click();
  await expect(dialog).toBeHidden();
  return link;
}

/**
 * Окно клиента без входа. Pre-Prod закрыт Vercel — переносится только cookie _vercel_jwt из сессии preprod-ttp
 * (без сессии Techory). Параметры окна — из текущего проекта.
 */
export async function openCustomerContext(browser: Browser, testInfo: TestInfo): Promise<{ context: BrowserContext; page: Page }> {
  const file = path.resolve(__dirname, '../../../auth', `${ROLE}.json`);
  if (!fs.existsSync(file)) throw new Error(`Нет сессии «${ROLE}» (.qa/auth/${ROLE}.json) — нужен cookie _vercel_jwt. Запусти npm run qa-login:manual -- ${ROLE}`);
  const state = JSON.parse(fs.readFileSync(file, 'utf8')) as { cookies: { name: string }[] };
  const cookies = state.cookies.filter((c) => c.name === '_vercel_jwt');
  const projectUse = testInfo.project.use as Record<string, unknown>;
  const opts: BrowserContextOptions = {};
  for (const k of CONTEXT_KEYS) if (projectUse[k] !== undefined) (opts as Record<string, unknown>)[k] = projectUse[k];
  const context = await browser.newContext({ ...opts, storageState: { cookies: cookies as never, origins: [] } });
  return { context, page: await context.newPage() };
}

/** Страница /pay?t=…: «<Company>», «Amount due», сумма, «Job #JOB-…», кнопка «Pay $N»; не «not valid». */
export async function expectPayPage(page: Page, amount: string, jobNo: string) {
  await expect(page.getByText(COMPANY, { exact: true }).first()).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('Amount due', { exact: true })).toBeVisible();
  await expect(page.getByText(amountRe(amount)).first()).toBeVisible();
  await expect(page.getByText(`Job ${jobNo}`, { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: `Pay ${amount}` })).toBeVisible();
  await expect(page.getByText(/not valid/i)).toHaveCount(0);
}

/** Stripe Checkout (test mode): карта 4242 4242 4242 4242 — только Pre-Prod. Возврат — /pay?…&paid=1. */
export async function payOnStripeCheckout(page: Page) {
  await page.waitForURL(/checkout\.stripe\.com/, { timeout: 30_000 });
  const email = page.getByLabel('Email');
  if ((await email.count()) && (await email.first().isEditable()) && (await email.first().inputValue()) === '') {
    await email.first().fill('qa-auto@example.com');
  }
  await page.getByPlaceholder('1234 1234 1234 1234').fill('4242424242424242');
  await page.getByPlaceholder('MM / YY').fill('12 / 34');
  await page.getByPlaceholder('CVC').fill('123');
  await page.getByLabel('Cardholder name').fill('QA-AUTO Test');
  const country = page.getByLabel('Country or region');
  if (await country.count()) await country.selectOption('US');
  const zip = page.getByPlaceholder(/ZIP/i);
  if (await zip.count()) await zip.fill('12345');
  await page.getByTestId('hosted-payment-submit-button').or(page.getByRole('button', { name: /^Pay$/ })).first().click();
}

/** Строка Payment history (таблица работы). */
export function historyRow(page: Page, text: RegExp | string): Locator {
  return page.getByRole('main').getByRole('row').filter({ hasText: text });
}
